//! Algorithm R: `notary-cards::policy` must reproduce the TypeScript verifier's verdict on every case in
//! `notary/vectors/cards/policy_cases.json` (generated by `gen-notary-conformance.ts`).
use notary_cards::policy::{read_policy, requester_allowed};
use notary_cards::stages::Roots;
use notary_cards::World;
use serde_json::{json, Value};

#[test]
fn rust_agrees_with_typescript_on_every_policy_case() {
    let p = std::path::PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../../../vectors/cards/policy_cases.json");
    let file: Value = serde_json::from_str(&std::fs::read_to_string(p).expect("run gen-notary-conformance.ts")).unwrap();
    let cases = file["cases"].as_array().unwrap();
    assert!(cases.len() >= 21);
    let mut bad = vec![];
    for c in cases {
        let world = World::from_json(&c["world"]).unwrap();
        let trusted: Vec<String> = c["config"]["trustedRoots"].as_array().unwrap().iter().map(|x| x.as_str().unwrap().into()).collect();
        let roots = Roots { trusted: &trusted, app_certification: "", login_service: "", max_depth: c["config"].get("maxChainDepth").and_then(Value::as_u64).unwrap_or(64) as usize };
        let now = notary_types::formats::parse_timestamp(c["config"]["nowIso"].as_str().unwrap()).unwrap();
        let replicas: Vec<String> = c["replica_cards"].as_array().unwrap().iter().map(|x| x.as_str().unwrap().into()).collect();
        let got = match read_policy(&world, c["policy_id"].as_str().unwrap(), c["policy_state_cid"].as_str().unwrap(), &replicas, &roots, now) {
            Err(code) => json!({ "ok": false, "code": code }),
            Ok(r) => {
                let mut v = json!({ "ok": true, "policy_address": r.policy_address, "notary": r.notary, "approved_notaries": r.approved_notaries });
                if !c["predicate"].is_null() {
                    v["requester_allowed"] = json!(requester_allowed(&world, &c["job"], &c["predicate"], &r.policy_address, &roots, now));
                }
                v
            }
        };
        if got != c["expect"] {
            bad.push(format!("{}: TypeScript {} / Rust {}", c["id"], c["expect"], got));
        }
    }
    assert!(bad.is_empty(), "{}", bad.join("\n"));
}
